class Solution {
public:
    int jump(vector<int>& nums) {
        int jumps = 0;
        int curr_end = 0;
        int farthest = 0;
        for (int i = 0; i < (int)nums.size() - 1; ++i) {
            farthest = max(farthest, i + nums[i]);
            if (i == curr_end) {
                jumps++;
                curr_end = farthest;
            }
        }
        return jumps;
    }
};

class Solution {
    public int jump(int[] nums) {
        int jumps = 0;
        int currEnd = 0;
        int farthest = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == currEnd) {
                jumps++;
                currEnd = farthest;
            }
        }
        return jumps;
    }
}

